-- VistaBalayan database fixes for Supabase SQL Editor
-- Run this in Supabase Dashboard > SQL Editor with owner/service privileges.

-- Let the officer UI see profile rows so Staff/User counts match the database.
DO $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM pg_policies
    WHERE schemaname = 'public' AND tablename = 'profiles' AND policyname = 'Authenticated users can read profiles'
  ) THEN
    CREATE POLICY "Authenticated users can read profiles"
      ON public.profiles
      FOR SELECT
      TO authenticated
      USING (true);
  END IF;
END $$;

-- Let authenticated officer UI update establishment metadata/images.
DO $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM pg_policies
    WHERE schemaname = 'public' AND tablename = 'establishments' AND policyname = 'Authenticated users can update establishments'
  ) THEN
    CREATE POLICY "Authenticated users can update establishments"
      ON public.establishments
      FOR UPDATE
      TO authenticated
      USING (true)
      WITH CHECK (true);
  END IF;
END $$;

